param([string]$ModelPath = "")
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
$Here=(Resolve-Path (Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) "..\..")).Path;$Cfg=Get-Content (Join-Path $Here "config\p0_target.json") -Raw -Encoding UTF8 | ConvertFrom-Json;$OutDir=Join-Path $Here "results";$ResultPath=Join-Path $OutDir "p7j_ab_results.json";$SummaryPath=Join-Path $OutDir "p7j_summary.json";$ProvPath=Join-Path $OutDir "shader_provenance.json";$ShaderDir=Join-Path $Here "compiled_shaders";$ExePath=Join-Path $Here "arcllm_p7j.exe";New-Item -ItemType Directory -Force -Path $OutDir|Out-Null
Write-Host "=== ArcLLM P7-J - FFN vec4-dequant A/B ===";Write-Host "";& py -3 (Join-Path $Here "tests\test_p7j_package.py");if($LASTEXITCODE -ne 0){throw "P7-J package audit failed before execution."};if(-not $ModelPath){$ModelPath=$Cfg.model_path};Write-Host "Model: $ModelPath";if(-not(Test-Path $ModelPath)){throw "Frozen model not found: $ModelPath"};$TargetHash=(Get-FileHash -Algorithm SHA256 $ModelPath).Hash.ToUpperInvariant();if($TargetHash -ne $Cfg.sha256){throw "Target SHA256 mismatch"};Write-Host "Target SHA256: PASS"
powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $Here "tools\compile_p7j_shaders.ps1");if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};if(-not(Test-Path -LiteralPath $ProvPath)){throw "P7-J shader provenance missing after compile"};$ProvObj=Get-Content -LiteralPath $ProvPath -Raw -Encoding UTF8|ConvertFrom-Json;if(@($ProvObj.compiled).Count -ne 17){throw "P7-J shader provenance count mismatch"};powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $Here "tools\build_p7j.ps1");if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$StdoutPath=Join-Path $OutDir "p7j.stdout.txt";$StderrPath=Join-Path $OutDir "p7j.stderr.txt";Remove-Item $StdoutPath,$StderrPath,$ResultPath,$SummaryPath -ErrorAction SilentlyContinue;$Proc=Start-Process -FilePath $ExePath -ArgumentList @("--model",$ModelPath,"--shader-dir",$ShaderDir,"--out",$ResultPath) -NoNewWindow -Wait -PassThru -RedirectStandardOutput $StdoutPath -RedirectStandardError $StderrPath;if(Test-Path $StdoutPath){Get-Content $StdoutPath};if(Test-Path $StderrPath){$ErrText=Get-Content $StderrPath -Raw;if($ErrText){Write-Host "stderr saved: results\p7j.stderr.txt"}};if(-not(Test-Path $ResultPath)){throw "P7-J did not create result JSON"};$ResultObj=Get-Content $ResultPath -Raw -Encoding UTF8|ConvertFrom-Json;$SummaryObj=[ordered]@{schema="arcllm.p7j.summary.v1";target_sha256=$TargetHash;process_exit_code=$Proc.ExitCode;status=$ResultObj.status;optimized_family=$ResultObj.scope.optimized_family;attention_projection_tiling_frozen=$ResultObj.scope.attention_projection_tiling_frozen;vec4_q4_pass=$ResultObj.regression.vec4_q4_pass;vec4_q6_pass=$ResultObj.regression.vec4_q6_pass;baseline_p7g_pp512_tok_s=$ResultObj.ab_pp512.baseline_tok_s;optimized_pp512_tok_s=$ResultObj.ab_pp512.optimized_tok_s;pp512_wall_speedup=$ResultObj.ab_pp512.wall_speedup;min_speedup_gate=$ResultObj.ab_pp512.min_speedup_gate;speedup_pass=$ResultObj.ab_pp512.speedup_pass;top1_match_all_trials=$ResultObj.ab_pp512.top1_match_all_trials;logits_match_all_trials=$ResultObj.ab_pp512.logits_match_all_trials;tg128_unmodified_tok_s=$ResultObj.tg128_unmodified.tok_s_wall;p7j_gate_pass=$ResultObj.p7j_gate.pass;p7_closed=$ResultObj.p7j_gate.p7_closed};$SummaryJson=$SummaryObj|ConvertTo-Json -Depth 8;[IO.File]::WriteAllText($SummaryPath,$SummaryJson,(New-Object Text.UTF8Encoding($false)));Write-Host "";Write-Host "Result:";Write-Host "  results\shader_provenance.json";Write-Host "  results\p7j_ab_results.json";Write-Host "  results\p7j_summary.json";if(($Proc.ExitCode -ne 0)-or(-not $ResultObj.p7j_gate.pass)){exit 20};exit 0
